,"order":35,"period":"6º Período","name":"ELETIVA","hours":60},{"source":"ped_integrada","order":36,"period":"6º Período","name":"PRÁTICAS PEDAGÓGICAS NO ENSINO MÉDIO","hours":60},{"source":"ped_integrada","order":37,"period":"6º Período","name":"EXTENSÃO INTEGRADA IV","hours":80},{"source":"ped_integrada","order":38,"period":"6º Período","name":"ESTEM- ESTÁGIO SUPERVISIONADO- DOCÊNCIA NO ENSINO MÉDIO","hours":60},{"source":"ped_integrada","order":39,"period":"7º Período","name":"FUNDAMENTOS DA SUPERVISÃO EDUCACIONAL","hours":60},{"source":"ped_integrada","order":40,"period":"7º Período","name":"EDUCAÇÃO PROFISSIONAL E TRABALHO","hours":60},{"source":"ped_integrada","order":41,"period":"7º Período","name":"EDUCAÇÃO QUILOMBOLA, INDÍGENA E NO CAMPO","hours":60},{"source":"ped_integrada","order":42,"period":"7º Período","name":"TCC I","hours":60},{"source":"ped_integrada","order":43,"period":"7º Período","name":"ELETIVA 2","hours":60},{"source":"ped_integrada","order":44,"period":"7º Período","name":"PRÁTICAS PEDAGÓGICAS EM CONTEXTOS NÃO ESCOLARES","hours":60},{"source":"ped_integrada","order":45,"period":"7º Período","name":"ESTOE- ESTÁGIO SUPERVISIONADO- GESTÃO DE ORGANIZAÇÕES ESCOLARES E NÃO-ESCOLARES","hours":80},{"source":"ped_integrada","order":46,"period":"8º Período","name":"FUNDAMENTOS DA INSPEÇÃO ESCOLAR","hours":60},{"source":"ped_integrada","order":47,"period":"8º Período","name":"TCC II","hours":60},{"source":"ped_integrada","order":48,"period":"8º Período","name":"ELETIVA 3","hours":60},{"source":"ped_integrada","order":49,"period":"8º Período","name":"EJA83- PRÁTICAS PEDAGÓGICAS NA EJA","hours":60},{"source":"log_trs","order":1,"period":"1º Período","name":"Fundamentos de Gestão e Logística","hours":60},{"source":"log_trs","order":2,"period":"1º Período","name":"Introdução a Economia","hours":60},{"source":"log_trs","order":3,"period":"1º Período","name":"Matemática Básica","hours":60},{"source":"log_trs","order":4,"period":"1º Período","name":"Gestão de Pessoas","hours":60},{"source":"log_trs","order":5,"period":"1º Período","name":"Planejamento de Marketing","hours":60},{"source":"log_trs","order":6,"period":"1º Período","name":"Metodologia da Pesquisa Científica","hours":60},{"source":"log_trs","order":7,"period":"1º Período","name":"Saúde e Segurança no trabalho","hours":60},{"source":"log_trs","order":8,"period":"1º Período","name":"Ética e Responsabilidade Empresarial","hours":60},{"source":"log_trs","order":9,"period":"2º Período","name":"Sistemas de armazenagem e movimentação de cargas","hours":60},{"source":"log_trs","order":10,"period":"2º Período","name":"Estatística","hours":60},{"source":"log_trs","order":11,"period":"2º Período","name":"Gestão da qualidade","hours":60},{"source":"log_trs","order":12,"period":"2º Período","name":"Planejamento e Controle de Produção Integrado a Logística","hours":60},{"source":"log_trs","order":13,"period":"2º Período","name":"Gestão Sustentável","hours":60},{"source":"log_trs","order":14,"period":"2º Período","name":"Gestão de Projetos","hours":60},{"source":"log_trs","order":15,"period":"2º Período","name":"Empreendedorismo e Inovação","hours":60},{"source":"log_trs","order":16,"period":"2º Período","name":"Optativa 1","hours":60},{"source":"log_trs","order":17,"period":"3º Período","name":"Administração de Materiais","hours":60},{"source":"log_trs","order":18,"period":"3º Período","name":"Gestão da Cadeia de Suprimentos","hours":60},{"source":"log_trs","order":19,"period":"3º Período","name":"Transportes na logística","hours":60},{"source":"log_trs","order":20,"period":"3º Período","name":"Gestão de Custos logísticos","hours":60},{"source":"log_trs","order":21,"period":"3º Período","name":"Matemática Financeira","hours":60},{"source":"log_trs","order":22,"period":"3º Período","name":"Logística Internacional","hours":60},{"source":"log_trs","order":23,"period":"3º Período","name":"Projeto Integrador I","hours":60},{"source":"log_trs","order":24,"period":"3º Período","name":"Projeto de Extensão 1","hours":90},{"source":"log_trs","order":25,"period":"4º Período","name":"Transporte de Passageiros","hours":60},{"source":"log_trs","order":26,"period":"4º Período","name":"Comércio Exterior","hours":60},{"source":"log_trs","order":27,"period":"4º Período","name":"Sistemas de Informação Logístico","hours":60},{"source":"log_trs","order":28,"period":"4º Período","name":"Logística Reversa","hours":60},{"source":"log_trs","order":29,"period":"4º Período","name":"Comportamento Organizacional","hours":60},{"source":"log_trs","order":30,"period":"4º Período","name":"Optativa 2","hours":60},{"source":"log_trs","order":31,"period":"4º Período","name":"Projeto Integrador II","hours":60},{"source":"log_trs","order":32,"period":"4º Período","name":"Projeto de Extensão 2","hours":100}]$dados$::jsonb;
 logins jsonb:=$dados$[{"unit":"DCX","email":"direcao@faeterj-dcx.faetec.rj.gov.br"},{"unit":"CGO","email":"direcao@faeterj-cgo.faetec.rj.gov.br"},{"unit":"FMO","email":"direcao@faeterj-rio.edu.br"},{"unit":"PTR","email":"direcao@faeterj-petropolis.edu.br"},{"unit":"ISERJ","email":"direcao.dg@iserj.edu.br"},{"unit":"ISEPAM","email":"direcao@isepam.edu.br"},{"unit":"PRC","email":"direcao@faeterj-prc.faetec.rj.gov.br"},{"unit":"BJI","email":"direcao@faeterj-bji.faetec.rj.gov.br"},{"unit":"ITP","email":"direcao@faeterj-itp.faetec.rj.gov.br"},{"unit":"SAP","email":"direcao@faeterj-sap.faetec.rj.gov.br"},{"unit":"TRS","email":"direcao@faeterj-trs.faetec.rj.gov.br"}]$dados$::jsonb;
 m record;u record;c record;d record;l record;
 quantidade integer;unidade_id_resolvida bigint;curso_id_resolvido bigint;matriz_id_resolvida bigint;componente_id_resolvido bigint;usuario_id_resolvido bigint;
 matrizes_processadas integer:=0;componentes_processados integer:=0;logins_processados integer:=0;
 senha_inicial text:='pbkdf2_sha256$1200000$iamocBgkIEJijEhYuPfx3m$plHm3yY8yYhQXaguUqlAMvUmFTVLtjhQwjmca8xoJAQ=';
BEGIN
 IF to_regclass('public.harpiadb_nucleo_unidade') IS NULL OR to_regclass('public.harpiadb_cursos_curso') IS NULL OR to_regclass('public.harpiadb_cursos_curso_unidade') IS NULL OR to_regclass('public.harpiadb_cursos_matriz_curricular') IS NULL OR to_regclass('public.harpiadb_cursos_matriz_unidades') IS NULL OR to_regclass('public.harpiadb_cursos_componente_curricular') IS NULL OR to_regclass('public.harpiadb_cursos_componente_matriz') IS NULL OR to_regclass('public.harpiadb_contas_usuario') IS NULL THEN RAISE EXCEPTION 'Schema Harpia esperado não foi encontrado.';END IF;
 EXECUTE 'ALTER TABLE public.harpiadb_cursos_componente_matriz ADD COLUMN IF NOT EXISTS nome_temporario varchar(255)';
 EXECUTE 'UPDATE public.harpiadb_cursos_componente_matriz SET nome_temporario = '''' WHERE nome_temporario IS NULL';
 EXECUTE 'ALTER TABLE public.harpiadb_cursos_componente_matriz ALTER COLUMN nome_temporario SET DEFAULT '''', ALTER COLUMN nome_temporario SET NOT NULL, ALTER COLUMN componente_curricular_id DROP NOT NULL';
 INSERT INTO public.django_migrations(app,name,applied) SELECT 'courses','0007_matrixcomponent_disciplina_temporaria',CURRENT_TIMESTAMP WHERE NOT EXISTS(SELECT 1 FROM public.django_migrations WHERE app='courses' AND name='0007_matrixcomponent_disciplina_temporaria');
 FOR m IN SELECT * FROM jsonb_to_recordset(matrizes) AS x(key text,source text,course text,unit text,name text) LOOP
  SELECT * INTO u FROM jsonb_to_recordset(unidades) AS x(key text,siglas jsonb,nomes jsonb) WHERE x.key=m.unit;
  SELECT count(*),min(b.id) INTO quantidade,unidade_id_resolvida FROM public.harpiadb_nucleo_unidade b WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(u.nomes)a(valor) WHERE lower(btrim(b.nome))=lower(btrim(a.valor)));
  IF quantidade=0 THEN SELECT count(*),min(b.id) INTO quantidade,unidade_id_resolvida FROM public.harpiadb_nucleo_unidade b WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(u.siglas)a(valor) WHERE lower(btrim(b.sigla))=lower(btrim(a.valor)));END IF;
  IF quantidade=0 THEN RAISE EXCEPTION 'Unidade % não encontrada.',m.unit;ELSIF quantidade>1 THEN RAISE EXCEPTION 'Unidade % ambígua: % correspondências.',m.unit,quantidade;END IF;
  SELECT * INTO c FROM jsonb_to_recordset(cursos) AS x(key text,nome text,sigla text,siglas jsonb,nomes jsonb) WHERE x.key=m.course;
  SELECT count(*),min(b.id) INTO quantidade,curso_id_resolvido FROM public.harpiadb_cursos_curso b WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(c.siglas)a(valor) WHERE lower(btrim(b.sigla))=lower(btrim(a.valor)));
  IF quantidade=0 THEN SELECT count(*),min(b.id) INTO quantidade,curso_id_resolvido FROM public.harpiadb_cursos_curso b WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(c.nomes)a(valor) WHERE lower(btrim(b.nome))=lower(btrim(a.valor)));END IF;
  IF quantidade>1 THEN RAISE EXCEPTION 'Curso % ambíguo: % correspondências.',m.course,quantidade;ELSIF quantidade=0 THEN INSERT INTO public.harpiadb_cursos_curso(nome,sigla)VALUES(c.nome,c.sigla)RETURNING id INTO curso_id_resolvido;END IF;
  UPDATE public.harpiadb_cursos_curso_unidade SET ativo=true WHERE curso_id=curso_id_resolvido AND unidade_id=unidade_id_resolvida;
  IF NOT FOUND THEN INSERT INTO public.harpiadb_cursos_curso_unidade(curso_id,unidade_id,ativo)VALUES(curso_id_resolvido,unidade_id_resolvida,true);END IF;
  SELECT count(*),min(b.id) INTO quantidade,matriz_id_resolvida FROM public.harpiadb_cursos_matriz_curricular b WHERE b.curso_id=curso_id_resolvido AND b.nome=m.name AND b.periodo_letivo='2026.2';
  IF quantidade>1 THEN RAISE EXCEPTION 'Matriz % ambígua: % correspondências.',m.key,quantidade;ELSIF quantidade=0 THEN INSERT INTO public.harpiadb_cursos_matriz_curricular(curso_id,nome,is_vigente,is_rascunho,criada_em,periodo_letivo,turno)VALUES(curso_id_resolvido,m.name,true,false,CURRENT_TIMESTAMP,'2026.2',NULL)RETURNING id INTO matriz_id_resolvida;ELSE UPDATE public.harpiadb_cursos_matriz_curricular SET is_vigente=true,is_rascunho=false WHERE id=matriz_id_resolvida;END IF;
  INSERT INTO public.harpiadb_cursos_matriz_unidades(curriculummatrix_id,unidade_id)SELECT matriz_id_resolvida,unidade_id_resolvida WHERE NOT EXISTS(SELECT 1 FROM public.harpiadb_cursos_matriz_unidades mu WHERE mu.curriculummatrix_id=matriz_id_resolvida AND mu.unidade_id=unidade_id_resolvida);
  FOR d IN SELECT * FROM jsonb_to_recordset(componentes) AS x(source text,"order" integer,period text,name text,hours integer) WHERE x.source=m.source ORDER BY x."order" LOOP
   SELECT count(*) INTO quantidade FROM public.harpiadb_cursos_componente_matriz mc WHERE mc.matriz_id=matriz_id_resolvida AND lower(btrim(mc.periodo))=lower(btrim(d.period)) AND lower(btrim(COALESCE((SELECT cc.nome FROM public.harpiadb_cursos_componente_curricular cc WHERE cc.id=mc.componente_curricular_id),mc.nome_temporario)))=lower(btrim(d.name));
   IF quantidade>0 THEN
    UPDATE public.harpiadb_cursos_componente_matriz mc SET carga_horaria=d.hours,creditos=(d.hours/20)::smallint,carga_horaria_semanal=round(d.hours::numeric/20,2) WHERE mc.matriz_id=matriz_id_resolvida AND lower(btrim(mc.periodo))=lower(btrim(d.period)) AND lower(btrim(COALESCE((SELECT cc.nome FROM public.harpiadb_cursos_componente_curricular cc WHERE cc.id=mc.componente_curricular_id),mc.nome_temporario)))=lower(btrim(d.name));
   ELSE
    SELECT CASE WHEN count(*)=1 THEN min(cc.id) END INTO componente_id_resolvido FROM public.harpiadb_cursos_componente_curricular cc WHERE lower(btrim(cc.nome))=lower(btrim(d.name)) AND cc.carga_horaria_padrao=d.hours;
    IF componente_id_resolvido IS NULL THEN SELECT CASE WHEN count(*)=1 THEN min(cc.id) END INTO componente_id_resolvido FROM public.harpiadb_cursos_componente_curricular cc WHERE lower(btrim(cc.nome))=lower(btrim(d.name));END IF;
    INSERT INTO public.harpiadb_cursos_componente_matriz(matriz_id,componente_curricular_id,nome_temporario,codigo,periodo,carga_horaria,creditos,docente_id,compartilhado,curso_compartilhado_id,carga_horaria_semanal,distribuicao_semanal,status,observacoes)VALUES(matriz_id_resolvida,componente_id_resolvido,CASE WHEN componente_id_resolvido IS NULL THEN d.name ELSE '' END,COALESCE((SELECT cc.codigo FROM public.harpiadb_cursos_componente_curricular cc WHERE cc.id=componente_id_resolvido),''),d.period,d.hours,(d.hours/20)::smallint,NULL,false,NULL,round(d.hours::numeric/20,2),'','SEM_PROFESSOR','');
   END IF;
   componentes_processados:=componentes_processados+1;
  END LOOP;
  matrizes_processadas:=matrizes_processadas+1;
 END LOOP;
 FOR l IN SELECT * FROM jsonb_to_recordset(logins) AS x(unit text,email text) LOOP
  SELECT * INTO u FROM jsonb_to_recordset(unidades) AS x(key text,siglas jsonb,nomes jsonb) WHERE x.key=l.unit;
  SELECT count(*),min(b.id) INTO quantidade,unidade_id_resolvida FROM public.harpiadb_nucleo_unidade b WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(u.nomes)a(valor) WHERE lower(btrim(b.nome))=lower(btrim(a.valor)));
  IF quantidade=0 THEN SELECT count(*),min(b.id) INTO quantidade,unidade_id_resolvida FROM public.harpiadb_nucleo_unidade b WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(u.siglas)a(valor) WHERE lower(btrim(b.sigla))=lower(btrim(a.valor)));END IF;
  IF quantidade<>1 THEN RAISE EXCEPTION 'Não foi possível resolver a unidade % do login %.',l.unit,l.email;END IF;
  SELECT count(*),min(id) INTO quantidade,usuario_id_resolvido FROM public.harpiadb_contas_usuario WHERE lower(email)=lower(l.email);
  IF quantidade>1 THEN RAISE EXCEPTION 'Mais de uma conta para %.',l.email;ELSIF quantidade=1 THEN UPDATE public.harpiadb_contas_usuario SET perfil='COORDENADOR_UNIDADE',unidade_id=unidade_id_resolvida,is_active=true WHERE id=usuario_id_resolvido;ELSE
   IF EXISTS(SELECT 1 FROM public.harpiadb_contas_usuario WHERE lower(username)=lower(l.email)) THEN RAISE EXCEPTION 'Username % já pertence a outra conta.',l.email;END IF;
   INSERT INTO public.harpiadb_contas_usuario(password,last_login,is_superuser,username,first_name,last_name,is_staff,is_active,date_joined,email,perfil,unidade_id,dados_submetidos,forcar_troca_senha)VALUES(senha_inicial,NULL,false,l.email,'Coordenação',l.unit,false,true,CURRENT_TIMESTAMP,l.email,'COORDENADOR_UNIDADE',unidade_id_resolvida,false,true);
  END IF;
  logins_processados:=logins_processados+1;
 END LOOP;
 IF matrizes_processadas<>15 OR componentes_processados<>484 OR logins_processados<>11 THEN RAISE EXCEPTION 'Contagens inesperadas: matrizes %, componentes %, logins %.',matrizes_processadas,componentes_processados,logins_processados;END IF;
 RAISE NOTICE 'SUCESSO: 15 matrizes, 484 componentes e 11 logins processados.';
END
$importacao$;
